def nav(active: str) -> str:
    links = "".join(
        f'<a href="{href}"{(" aria-current=\"page\"" if key == active else "")}>{label}</a>'
        for label, href, key in NAV
    )
    return f'''<header class="site-header"><div class="wrap header-inner">
      <a class="brand" href="index.html" aria-label="Janith Dasanayaka, home"><span class="brand-mark">jd<span>.</span></span><span class="brand-text">JANITH DASANAYAKA</span></a>
      <nav class="site-nav" id="site-nav" aria-label="Main navigation">{links}<a class="nav-contact" href="index.html#contact">Contact</a></nav>
      <div class="header-actions"><button class="theme-toggle" type="button" aria-label="Switch theme" title="Switch theme"><span class="theme-sun">{icon("sun")}</span><span class="theme-moon">{icon("moon")}</span></button><button class="menu-toggle" type="button" aria-label="Open menu" aria-controls="site-nav" aria-expanded="false"><span></span><span></span></button></div>
    </div></header>'''


