def page(title: str, description: str, active: str, body: str) -> str:
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#0b1020"><meta name="description" content="{description}">
<title>{title} | Janith Dasanayaka</title>
<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='13' fill='%230b1020'/%3E%3Ctext x='10' y='44' font-family='Arial,sans-serif' font-size='34' font-weight='700' fill='%23c4f27c'%3EJD%3C/text%3E%3C/svg%3E">
<script>try{{const p=localStorage.getItem('portfolio-theme');document.documentElement.dataset.theme=p||(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark')}}catch{{document.documentElement.dataset.theme='dark'}}</script>
<link rel="stylesheet" href="styles.css"><script src="script.js" defer></script></head><body>
<a class="skip-link" href="#main">Skip to content</a><div class="scroll-progress" aria-hidden="true"></div>{nav(active)}<main id="main">{body}</main>{footer()}</body></html>'''


